import os,json,hashlib,platform,subprocess,sys,time,tempfile,datetime,resource,itertools,functools
from pathlib import Path
resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3));resource.setrlimit(resource.RLIMIT_CPU,(120,120))
start=time.monotonic();root=Path.cwd()
sha=lambda b:hashlib.sha256(b).hexdigest()
def G(v,g):return (v^((v<<1)|(v<<2)))^(g!='t')^(2 if g=='p' and v%2==0 else 0)
def inv(x,g):
 assert x>=0
 n=x.bit_length()+8;v=0
 for i in range(n):
  if (G(v,g)^x)&(1<<i):v|=1<<i
 if v>>(n-2)==3:v-=1<<n
 else:assert v>>(n-2)==0
 assert G(v,g)==x
 return v

def B(x,q):
 a=inv(x,q)
 if a<0:return {'a':a,'class':'RAT'}
 b=inv(a,'p');v=4*b+3
 assert v%16=={'t':11,'u':7}[q] and G(G(v>>2,'p'),q)==x
 return {'a':a,'b':b,'B':v,'class':'POS' if b>=0 else 'NEG'}
assert B(27,'u')['B']==7 and B(7,'t')['B']==-5
@functools.lru_cache(None)
def member(v,k):
 if k<1 or v<=0 or v.bit_length()!=2*k-1:return None
 if k==1:return 'u' if v==1 else None
 # Avoid any head-pruning dependency: exact complete signed inverse recursion.
 for g in 'tup':
  par=inv(v,g)
  w=member(par,k-1)
  if w is not None:return w+g
 return None

def orbit(x):
 states=[x];w='';reason='cap'
 for _ in range(16):
  q={7:'u',11:'t'}.get(x%16)
  if q is None:reason='undefined-gate';break
  if any(f in w+q for f in ('uu','ttttt','ututtu')):reason='forbidden-factor';break
  w+=q;x=G(G(x>>2,'p'),q);states.append(x)
 return {'word':w,'states':states,'stop':reason}
base='uuuuuutu' # root u followed by five U,T,U
v=0
for g in base:v=G(v,g)
assert v==25715 and len(base)==8
rows=[];counter=None
for suffix in itertools.product('tup',repeat=4):
 word=base+''.join(suffix)+'p';x=0
 for g in word:x=G(x,g)
 assert len(word)==13 and x.bit_length()==25
 # Keep same source-head condition from the original experiment.
 source=0
 for g in word[:-1]:source=G(source,g)
 assert source>>8==25715 # period-four A core
 row={'word':word,'x':x,'source':source}
 if x%16 not in (7,11):row['eligible']=False;rows.append(row);continue
 row['eligible']=True;row['orbit']=orbit(x);preds={}
 for q in 'tu':
  r=B(x,q)
  if r['class']=='POS':
   r['ordinary_word']=member(r['B'],12)
   r['admissible_prepend']=not any(f in q+row['orbit']['word'] for f in ('uu','ttttt','ututtu'))
  preds[q]=r
 row['predecessors']=preds;rows.append(row)
 if not any(r.get('ordinary_word') is not None and r.get('admissible_prepend') for r in preds.values()):
  counter=row;break
summary={'tested_words':len(rows),'eligible':sum(r['eligible'] for r in rows),'counter':counter,'membership_memo':member.cache_info()._asdict()}
source=Path(__file__).read_text()
record={'experiment_id':'problem1-ordinary-gated-inverse-20260905','timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'question':'problem1','hypothesis':'Every ordinary child of the fixed core25715 with a defined current forced step has some positive ordinary admissible forced predecessor.','backend':'lead-packed-inverse-and-complete-membership-recursion','parameters':{'source_head':25715,'base_word':base,'suffix_length':4,'suffix_order':'tup','final_generator':'p','max_words':81,'orbit_cap':16,'stop':'first eligible endpoint with no ordinary admissible predecessor','memory_bytes_cap':1024**3,'cpu_seconds_cap':120},'hardware':{'machine':platform.machine(),'cpu_count':os.cpu_count()},'software':{'python':sys.version,'platform':platform.platform()},'runtime_seconds':time.monotonic()-start,'result_summary':summary,'results':{'rows':rows},'source_text':source,'result_hashes':{'source_sha256':sha(source.encode()),'summary_sha256':sha(json.dumps(summary,sort_keys=True).encode())},'status':'refuted' if counter else 'inconclusive','proof_scope':'Fixed-source words only; explicit ordinary witness and complete signed predecessors. Not a long-decoder-word or genuine-three-return assertion.','interpretation':'First real-gate predecessor obstruction' if counter else 'No counter in declared finite set','limitations':['The original k13 is below decoder u,k18 threshold.','Short ordinary forward continuation does not certify a three-return occurrence.','No claim of global minimality; loop stops at first counter in fixed word order.']}
out=Path('/tmp/astra_gate_membership.json');fd,tmp=tempfile.mkstemp(dir=out.parent,prefix=out.name+'.')
with os.fdopen(fd,'w') as f:json.dump(record,f,indent=2,sort_keys=True);f.write('\n');f.flush();os.fsync(f.fileno())
os.replace(tmp,out);print(json.dumps(summary,indent=2))

