  "source_text": "import os, json, hashlib, platform, subprocess, sys, time, tempfile, datetime, resource, functools\nfrom pathlib import Path\nresource.setrlimit(resource.RLIMIT_AS, (1024**3, 1024**3))\nresource.setrlimit(resource.RLIMIT_CPU, (120, 120))\nstart = time.monotonic()\nsha = lambda b: hashlib.sha256(b).hexdigest()\nFORB = ('uu', 'ttttt', 'ututtu')\n# --- Independent Boolean-cell forward (signed, Z2 boundary v_-1=v_-2=0) ---\ndef fwd_bool(v, g, nbits=None):\n    if nbits is None:\n        nbits = max(1, (v.bit_length() if v >= 0 else (v % (1 << 24)).bit_length()) + 4)\n        if v < 0:\n            nbits = 32\n    out = 0\n    veven = (v & 1) == 0\n    for i in range(nbits):\n        vi = (v >> i) & 1\n        vim1 = ((v >> (i-1)) & 1) if i-1 >= 0 else 0\n        vim2 = ((v >> (i-2)) & 1) if i-2 >= 0 else 0\n        ti = vi ^ (vim1 | vim2)\n        if g == 't':\n            oi = ti\n        elif g == 'u':\n            oi = ti ^ (1 if i == 0 else 0)\n        else:\n            oi = ti ^ (1 if i == 0 else 0) ^ (1 if (i == 1 and veven) else 0)\n        if oi:\n            out |= (1 << i)\n    return out\n# --- Independent Boolean-cell inverse (triangular bit solver) ---\ndef inv_bool(x, g):\n    assert isinstance(x, int) and x >= 0\n    n = x.bit_length() + 10\n    if n < 12:\n        n = 12\n    if g == 't':\n        c = x\n    elif g == 'u':\n        c = x ^ 1\n    else:\n        c = x ^ 1 ^ (2 if (x & 1) else 0)\n    v = 0\n    for i in range(n):\n        ci = (c >> i) & 1\n        vim1 = ((v >> (i-1)) & 1) if i-1 >= 0 else 0\n        vim2 = ((v >> (i-2)) & 1) if i-2 >= 0 else 0\n        vi = ci ^ (vim1 | vim2)\n        if vi:\n            v |= (1 << i)\n    top = v >> (n-2)\n    if top == 0:\n        sv = v\n    elif top == 3:\n        sv = v - (1 << n)\n    else:\n        raise AssertionError('non-integer tail')\n    return sv\n# packed cross-check only (not the decision path)\ndef G_pack(v, g):\n    return (v ^ ((v << 1) | (v << 2))) ^ (0 if g == 't' else 1) ^ (2 if (g == 'p' and v % 2 == 0) else 0)\ndef replay(word):\n    v = 0\n    for g in word:\n        v = fwd_bool(v, g, nbits=max(8, v.bit_length() + 5) if v >= 0 else 32)\n    return v\ndef orbit_bool(x0):\n    states = [x0]; w = ''\n    x = x0\n    reason = 'cap'\n    for _ in range(16):\n        q = {7: 'u', 11: 't'}.get(x % 16)\n        if q is None:\n            reason = 'undefined-gate'; break\n        if any(f in (w + q) for f in FORB):\n            reason = 'forbidden-factor'; break\n        w += q\n        x = fwd_bool(fwd_bool(x, 'p', nbits=x.bit_length()+6) >> 2, q, nbits=x.bit_length()+6)\n        states.append(x)\n    return {'word': w, 'states': states, 'stop': reason}\n# named targets\ncounter_word = 'uuuuuutuuputp'\nbase_word = 'uuuuuutu'\nassert replay(base_word) == 25715 and len(base_word) == 8\ncx = replay(counter_word)\nassert cx == 29203579, cx\nassert len(counter_word) == 13 and cx.bit_length() == 25\ncsource = replay(counter_word[:-1])\nassert csource == 6583240, csource\nassert csource >> 8 == 25715\nob = orbit_bool(cx)\nassert ob['word'] == 'tu' and ob['states'][:3] == [29203579, 116608679, 467256739] and ob['stop'] == 'undefined-gate'\n# nongated corrected construction\ninner = 'UUUUUTUTUUU'.lower()\nng_word = 'u' + inner + 'p'\nassert ng_word == 'uuuuuututuuup' and len(ng_word) == 13, ng_word\nngx = replay(ng_word)\nassert ngx == 29203507, ngx\nassert ngx % 16 == 3\n# packed agreement on named orbit + roots (cross-check)\nfor vv, g in [(0,'u'),(25715,'u'),(cx,'t')]:\n    assert fwd_bool(vv, g, nbits=max(8, (vv.bit_length()+5))) == G_pack(vv, g)\n# forced predecessors via Boolean inverses\ndef Branch(x, q):\n    a = inv_bool(x, q)\n    if a < 0:\n        return {'a': a, 'class': 'RAT'}\n    b = inv_bool(a, 'p')\n    Bv = 4*b + 3\n    return {'a': a, 'b': b, 'B': Bv, 'class': 'POS' if b >= 0 else 'NEG'}\nbt = Branch(cx, 't'); bu = Branch(cx, 'u')\nassert bt == {'a': 6583205, 'b': 1822298, 'B': 7289195, 'class': 'POS'}, bt\nassert bu