onfirmed distinct (both B negative, no actual branch).',\n  'limitations': ['k13 below decoder u,k18 threshold; not a decoder counter', 'short continuation is not a genuine three-return', 'no minimality claim', 'existing-core labels are compatibility checks only'],\n  'status': 'refuted'}\nimport pathlib\nsrc = Path('/tmp/astra-gated-membership-review.py').read_text()\nrecord['source_text'] = src\nrecord['result_hashes'] = {'source_sha256': sha(src.encode()), 'summary_sha256': sha(json.dumps(summary, sort_keys=True).encode())}\nout = Path('/tmp/astra-gated-membership-review.json')\nfd, tmp = tempfile.mkstemp(dir=str(out.parent), prefix=out.name + '.')\nwith os.fdopen(fd, 'w') as f:\n    json.dump(record, f, indent=2, sort_keys=True); f.write(chr(10)); f.flush(); os.fsync(f.fileno())\nos.replace(tmp, out)\nprint(json.dumps(summary, indent=2))\n",
