import os,json,hashlib,platform,subprocess,sys,time,tempfile,datetime
from pathlib import Path
start=time.monotonic();root=Path.cwd()
sha=lambda b:hashlib.sha256(b).hexdigest()
runs={}
for name,stem in [('sign','astra-second-inverse-muse'),('ordinary','astra-ordinary-second-sign-muse'),('gate','astra_gate_membership'),('gated_review','astra-gated-membership-review'),('prefix_certificate','astra-gated-prefix-certificate')]:
 p=Path('/tmp')/(stem+'.json')
 if not p.exists():continue
 s=Path('/tmp')/(stem+'.py');raw=p.read_text();original=json.loads(raw)
 source=s.read_text() if s.exists() else original['source_text']
 runs[name]={'original_path':str(p),'raw_json_text':raw,'raw_sha256':sha(raw.encode()),'executed_source_path':str(s),'source_text':source,'source_sha256':sha(source.encode()),'runtime_seconds':original['runtime_seconds']}
summary={name:json.loads(v['raw_json_text'])['result_summary'] for name,v in runs.items()}
source=Path(__file__).read_text()
record={'experiment_id':'problem1-composed-inverse-primary-20260905','timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'question':'problem1','hypothesis':'Determine whether existing core heads force second inverse positivity and whether a source ordinary generator restores that property.','backend':'muse-transducer-and-lead-gated-membership-provenance-wrapper','parameters':{'runs':list(runs),'runtime_scope':'Packaging only; each original computation retains its own runtime.','delegated_research_model':'opencode-go/muse-spark-1.3-contributor','gate_run_author':'lead'},'hardware':{'cpu_count':os.cpu_count(),'machine':platform.machine()},'software':{'python':sys.version,'platform':platform.platform()},'runtime_seconds':time.monotonic()-start,'result_summary':summary,'runs':runs,'source_text':source,'result_hashes':{'source_sha256':sha(source.encode()),'result_summary_sha256':sha(json.dumps(summary,sort_keys=True,separators=(',',':')).encode())},'status':'finite-exhaustive','proof_scope':'Exact finite transfer tables and bounded named witnesses; all-depth conclusions are separately derived in the accompanying note.','interpretation':'Two existing leading heads force positive second inverses; other heads have reachable mixed signs. No membership is inferred from a head.','limitations':['Original sign payload advertises l<=12 sampling that its source does not execute; actual search stops by l10, and no l12 claim is adopted.','Original sign inverse helper uses a cutoff at bit256; all its actual inputs are below that cutoff. The finite transition function has no such cutoff.','The original draft t initial state was incorrect; Muse corrected it to state6 before running transfers.','Second raw JSON was scope-edited after execution. Its record_sha256 hashes the edited body with the original run hash still inside. Independent replay reverses the documented scope edits, recovers original hash78f0f5eecfd3e6e7a7003e70d2d4604bc25766234adc8e0249f8ef4e8c67dbea, and validates this nested hash. Source and numerical results are unchanged.','Source records retain temporary paths as provenance; independent replay uses embedded sources/data from this committed wrapper.','Second raw run unnecessarily generated root frontiers through k10 to recover already known C8 histories and enumerated four-letter source suffixes. Its no-frontier/no-word-scan wording is inaccurate. No frontier construction is adopted as new evidence or repeated by independent verification.', 'The nongated ordinary counter has x3mod16; the separately recorded gated counter has only two actual branches. Neither refutes decoder-threshold/long-word or genuine-return backward closure.']}
record['inputs']={p:sha((root/p).read_bytes()) for p in ['proofs/informal/problem1_decoder_inverse_obstruction.md','results/problem1/20260905_frontier_head_independent.json']}
out=root/'results/problem1/20260905_composed_inverse_primary.json'
fd,tmp=tempfile.mkstemp(dir=out.parent,prefix=out.name+'.')
with os.fdopen(fd,'w') as f:json.dump(record,f,indent=2,sort_keys=True);f.write('\n');f.flush();os.fsync(f.fileno())
os.replace(tmp,out)
print('packaged',list(runs))
